// src/App.jsx
import React, { useState, useEffect } from "react";
import axios from "axios";
import "./App.css";

import ReactFlow, { MiniMap, Controls } from "react-flow-renderer";

// Basic nodes and edges for the flow chart
const initialNodes = [
  {
    id: "1",
    type: "input",
    data: { label: "Start Node" },
    position: { x: 250, y: 5 },
  },
  { id: "2", data: { label: "Node 2" }, position: { x: 100, y: 100 } },
  { id: "3", data: { label: "Node 3" }, position: { x: 400, y: 100 } },
  {
    id: "4",
    type: "output",
    data: { label: "End Node" },
    position: { x: 250, y: 200 },
  },
];

const initialEdges = [
  { id: "e1-2", source: "1", target: "2", animated: true },
  { id: "e1-3", source: "1", target: "3", animated: true },
  { id: "e2-4", source: "2", target: "4" },
  { id: "e3-4", source: "3", target: "4" },
];

const API_URL = "http://localhost:5000/api";

function App() {
  const [nodes, setNodes] = useState([]);
  const [pods, setPods] = useState([]);
  const [newNodeCPU, setNewNodeCPU] = useState(4);
  const [newPodCPU, setNewPodCPU] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch data from API
  const fetchData = async () => {
    try {
      setLoading(true);
      const [nodesResponse, podsResponse] = await Promise.all([
        axios.get(`${API_URL}/nodes`),
        axios.get(`${API_URL}/pods`),
      ]);

      setNodes(Object.values(nodesResponse.data));
      setPods(Object.values(podsResponse.data));
      setLoading(false);
    } catch (err) {
      setError("Failed to fetch data");
      setLoading(false);
      console.error(err);
    }
  };

  // Transform data for the graph visualization
  const transformData = () => {
    // Create nodes for visualization
    const graphNodes = [
      // Node containers
      ...nodes.map((node) => ({
        id: node.id,
        symbolType: "square",
        color: node.status === "Running" ? "#4CAF50" : "#F44336",
        size: 500,
        label: `Node: ${node.id.substring(0, 7)}...\nCPU: ${node.available_cpu}/${node.cpu}\nStatus: ${node.status}`,
      })),

      // Pods
      ...pods.map((pod) => ({
        id: pod.id,
        symbolType: "circle",
        color: pod.status === "Running" ? "#2196F3" : "#FFC107",
        size: 300,
        label: `Pod: ${pod.id.substring(0, 7)}...\nCPU: ${pod.cpu}\nStatus: ${pod.status}`,
      })),
    ];

    // Create links between nodes and their pods
    const graphLinks = pods
      .filter((pod) => pod.node_id) // Only pods assigned to nodes
      .map((pod) => ({
        source: pod.node_id,
        target: pod.id,
      }));

    setGraphData({
      nodes: graphNodes,
      links: graphLinks,
    });
  };

  // Create a new node
  const createNode = async () => {
    try {
      await axios.post(`${API_URL}/nodes`, { cpu_cores: newNodeCPU });
      fetchData();
    } catch (err) {
      setError("Failed to create node");
      console.error(err);
    }
  };

  // Create a new pod
  const createPod = async () => {
    try {
      await axios.post(`${API_URL}/pods`, { cpu_cores: newPodCPU });
      fetchData();
    } catch (err) {
      setError("Failed to create pod");
      console.error(err);
    }
  };

  // Delete a node
  const deleteNode = async (nodeId) => {
    try {
      await axios.delete(`${API_URL}/nodes/${nodeId}`);
      fetchData();
    } catch (err) {
      setError("Failed to delete node");
      console.error(err);
    }
  };

  // Initial data load
  useEffect(() => {
    fetchData();
    // Set up polling for updates
    const interval = setInterval(fetchData, 5000);
    return () => clearInterval(interval);
  }, []);

  // Transform data whenever nodes or pods change
  useEffect(() => {
    if (nodes.length > 0 || pods.length > 0) {
      transformData();
    }
  }, [nodes, pods]);

  if (loading && nodes.length === 0) {
    return <div className="loading">Loading cluster data...</div>;
  }

  return (
    <div className="app">
      <header>
        <h1>Kubernetes-like Cluster Visualization</h1>
      </header>

      <div className="controls">
        <div className="control-group">
          <h3>Add Node</h3>
          <input
            type="number"
            value={newNodeCPU}
            onChange={(e) => setNewNodeCPU(parseInt(e.target.value))}
            min="1"
            max="16"
          />
          <label>CPU Cores</label>
          <button onClick={createNode}>Create Node</button>
        </div>

        <div className="control-group">
          <h3>Add Pod</h3>
          <input
            type="number"
            value={newPodCPU}
            onChange={(e) => setNewPodCPU(parseInt(e.target.value))}
            min="1"
            max="8"
          />
          <label>CPU Cores</label>
          <button onClick={createPod}>Create Pod</button>
        </div>
      </div>

      {error && <div className="error">{error}</div>}

      <div className="cluster-stats">
        <div className="stat-box">
          <h3>Nodes: {nodes.length}</h3>
          <p>
            Running: {nodes.filter((node) => node.status === "Running").length}
          </p>
          <p>
            Unhealthy:{" "}
            {nodes.filter((node) => node.status !== "Running").length}
          </p>
        </div>
        <div className="stat-box">
          <h3>Pods: {pods.length}</h3>
          <p>
            Running: {pods.filter((pod) => pod.status === "Running").length}
          </p>
          <p>
            Offline: {pods.filter((pod) => pod.status !== "Running").length}
          </p>
        </div>
      </div>

      <div className="graph-container">
        {graphData.nodes.length > 0 ? (
          <Graph id="cluster-graph" data={graphData} config={graphConfig} />
        ) : (
          <p>
            No nodes or pods available. Create some to see the visualization.
          </p>
        )}
      </div>

      <div className="node-list">
        <h2>Node List</h2>
        <div className="list">
          {nodes.map((node) => (
            <div
              key={node.id}
              className={`node-card ${node.status.toLowerCase()}`}
            >
              <h3>Node: {node.id.substring(0, 10)}...</h3>
              <p>Status: {node.status}</p>
              <p>
                CPU: {node.available_cpu}/{node.cpu}
              </p>
              <p>Pods: {node.pods.length}</p>
              <button
                className="delete-btn"
                onClick={() => deleteNode(node.id)}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      </div>

      <div className="pod-list">
        <h2>Pod List</h2>
        <div className="list">
          {pods.map((pod) => (
            <div
              key={pod.id}
              className={`pod-card ${pod.status.toLowerCase()}`}
            >
              <h3>Pod: {pod.id.substring(0, 10)}...</h3>
              <p>Status: {pod.status}</p>
              <p>CPU: {pod.cpu}</p>
              <p>
                Node:{" "}
                {pod.node_id
                  ? pod.node_id.substring(0, 10) + "..."
                  : "Unassigned"}
              </p>
            </div>
          ))}
        </div>
      </div>
      <div style={{ height: 500 }}>
        <ReactFlow nodes={initialNodes} edges={initialEdges} fitView>
          <MiniMap />
          <Controls />
        </ReactFlow>
      </div>
    </div>
  );
}

export default App;
